import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Route, Routes, Link, useNavigate } from 'react-router-dom';
import Home from './components/Home';
import MotoristasList from './components/MotoristasList';
import BuscarMotorista from './components/BuscarMotorista';
import CadastrarMotorista from './components/CadastrarMotorista';
import Dashboard from './components/Dashboard';
import Login from './components/Login';
import './styles/global.css';

const App = () => {
    const [user, setUser] = useState(null);

    return (
        <Router>
            <AppContent user={user} setUser={setUser} />
        </Router>
    );
};

// Criando um novo componente para evitar erro do useNavigate()
const AppContent = ({ user, setUser }) => {
    const navigate = useNavigate();

    useEffect(() => {
        const token = localStorage.getItem('token');
        if (token) {
            setUser({ token });
        }
    }, []);

    const handleLogout = () => {
        localStorage.removeItem('token');
        setUser(null);
        navigate('/login'); // Agora isso não vai mais dar erro!
    };

    return (
        <div className="app-container">
            <nav className="navbar">
                <h1>🚗 CheckPort</h1>
                <div className="nav-links">
                    <Link to="/">🏠 Início</Link>
                    {user ? (
                        <>
                            <Link to="/listar">📋 Lista</Link>
                            <Link to="/buscar">🔍 Buscar</Link>
                            <Link to="/cadastrar">➕ Cadastrar</Link>
                            <Link to="/dashboard">📊 Dashboard</Link>
                            <button onClick={handleLogout}>🚪 Sair</button>
                        </>
                    ) : (
                        <Link to="/login">🔐 Login</Link>
                    )}
                </div>
            </nav>

            <div className="main-content">
                <Routes>
                    <Route path="/" element={<Home />} />
                    <Route path="/login" element={<Login setUser={setUser} />} />
                    {user && (
                        <>
                            <Route path="/listar" element={<MotoristasList />} />
                            <Route path="/buscar" element={<BuscarMotorista />} />
                            <Route path="/cadastrar" element={<CadastrarMotorista />} />
                            <Route path="/dashboard" element={<Dashboard />} />
                        </>
                    )}
                </Routes>
            </div>
        </div>
    );
};

export default App;
